INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_058_M1_S3', 'structural change', '3', 'structural change: Movement of economic activity, employment, and resources across sectors as an economy develops. In Growth and Structural Transformation, the focus is on the analysis, design, implementation, interpretation, or evaluation of structural change within Development Economics, particularly where the Growth and Structural Transformation module establishes its technical context.', 'SSD_COURSE_058_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M1_S4', 'industrialization', '4', 'industrialization: Expansion and transformation of manufacturing and related productive capabilities during economic development. In Growth and Structural Transformation, the focus is on the analysis, design, implementation, interpretation, or evaluation of industrialization within Development Economics, particularly where the Growth and Structural Transformation module establishes its technical context.', 'SSD_COURSE_058_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M2_S1', 'poverty measurement', '1', 'poverty measurement: Methods for defining, identifying, and quantifying poverty using measures such as poverty lines, incidence, depth, or severity. In Poverty and Inequality, the focus is on the analysis, design, implementation, interpretation, or evaluation of poverty measurement within Development Economics, particularly where the Poverty and Inequality module establishes its technical context.', 'SSD_COURSE_058_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M2_S2', 'inequality measures', '2', 'inequality measures: Statistical measures describing differences in income, wealth, consumption, or other valued outcomes across a population. In Poverty and Inequality, the focus is on the analysis, design, implementation, interpretation, or evaluation of inequality measures within Development Economics, particularly where the Poverty and Inequality module establishes its technical context.', 'SSD_COURSE_058_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M2_S3', 'redistribution', '3', 'redistribution: Policies that alter the distribution of income, wealth, or resources through taxes, transfers, or public provision. In Poverty and Inequality, the focus is on the analysis, design, implementation, interpretation, or evaluation of redistribution within Development Economics, particularly where the Poverty and Inequality module establishes its technical context.', 'SSD_COURSE_058_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M2_S4', 'multidimensional poverty', '4', 'multidimensional poverty: Poverty assessed across several dimensions such as health, education, housing, and living standards rather than income alone. In Poverty and Inequality, the focus is on the analysis, design, implementation, interpretation, or evaluation of multidimensional poverty within Development Economics, particularly where the Poverty and Inequality module establishes its technical context.', 'SSD_COURSE_058_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M3_S1', 'education', '1', 'education: Structured processes and institutions through which knowledge, skills, values, and capabilities are developed and transmitted across individuals and society. In Human Capital and Labour, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_058_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M3_S2', 'health', '2', 'health refers to a multidimensional condition of physical, mental, or social well-being considered in relation to individual, social, economic, and environmental determinants. In Human Capital and Labour, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_058_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M3_S3', 'labour markets', '3', 'labour markets: Markets in which workers supply labour and employers demand labour under institutional and economic conditions. In Human Capital and Labour, the focus is on the analysis, design, implementation, interpretation, or evaluation of labour markets within Development Economics, particularly where the Human Capital and Labour module establishes its technical context.', 'SSD_COURSE_058_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M3_S4', 'returns to human capital', '4', 'returns to human capital: Economic gains associated with investments in education, skills, health, or other productive capabilities. In Human Capital and Labour, the focus is on the analysis, design, implementation, interpretation, or evaluation of returns to human capital within Development Economics, particularly where the Human Capital and Labour module establishes its technical context.', 'SSD_COURSE_058_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M4_S1', 'property rights', '1', 'property rights: Rules defining rights to use, control, transfer, and benefit from assets and resources. In Institutions and Development, the focus is on the analysis, design, implementation, interpretation, or evaluation of property rights within Development Economics, particularly where the Institutions and Development module establishes its technical context.', 'SSD_COURSE_058_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M4_S2', 'governance', '2', 'governance: governance in Development Economics concerns legal rules, institutional mechanisms, duties, procedures, and compliance considerations governing governance. In Institutions and Development, the focus is on the analysis, design, implementation, interpretation, or evaluation of governance within Development Economics, particularly where the Institutions and Development module establishes its technical context.', 'SSD_COURSE_058_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M4_S3', 'political economy', '3', 'political economy: Study of how political institutions, power, and interests influence economic policies and outcomes. In Institutions and Development, the focus is on the analysis, design, implementation, interpretation, or evaluation of political economy within Development Economics, particularly where the Institutions and Development module establishes its technical context.', 'SSD_COURSE_058_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M4_S4', 'institutional quality', '4', 'institutional quality: How effectively institutions provide predictable rules, accountability, property protection, and support for economic activity. In Institutions and Development, the focus is on the analysis, design, implementation, interpretation, or evaluation of institutional quality within Development Economics, particularly where the Institutions and Development module establishes its technical context.', 'SSD_COURSE_058_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M5_S1', 'credit constraints', '1', 'credit constraints: Limits on borrowing that prevent households or firms from financing otherwise productive investments or consumption. In Markets, Finance and Development, the focus is on the analysis, design, implementation, interpretation, or evaluation of credit constraints within Development Economics, particularly where the Markets, Finance and Development module establishes its technical context.', 'SSD_COURSE_058_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M5_S2', 'financial inclusion', '2', 'financial inclusion: Access to and effective use of suitable financial services by households and firms. In Markets, Finance and Development, the focus is on the analysis, design, implementation, interpretation, or evaluation of financial inclusion within Development Economics, particularly where the Markets, Finance and Development module establishes its technical context.', 'SSD_COURSE_058_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M5_S3', 'market failures', '3', 'market failures: Conditions such as externalities, public goods, information asymmetry, or market power that prevent decentralized markets from achieving an efficient allocation of resources. In Markets, Finance and Development, the focus is on the analysis, design, implementation, interpretation, or evaluation of market failures within Development Economics, particularly where the Markets, Finance and Development module establishes its technical context.', 'SSD_COURSE_058_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M5_S4', 'informal institutions', '4', 'informal institutions: Unwritten norms, conventions, and social practices that shape economic behaviour alongside formal rules. In Markets, Finance and Development, the focus is on the analysis, design, implementation, interpretation, or evaluation of informal institutions within Development Economics, particularly where the Markets, Finance and Development module establishes its technical context.', 'SSD_COURSE_058_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M6_S1', 'program design', '1', 'program design: Structuring a development intervention by defining objectives, target groups, activities, delivery mechanisms, resources, and expected results. In Development Policy and Evaluation, the focus is on the analysis, design, implementation, interpretation, or evaluation of program design within Development Economics, particularly where the Development Policy and Evaluation module establishes its technical context.', 'SSD_COURSE_058_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M6_S2', 'cost-benefit analysis', '2', 'cost-benefit analysis: Comparison of the monetized benefits and costs of a policy or development intervention, adjusted where appropriate for timing and uncertainty. In Development Policy and Evaluation, the focus is on the analysis, design, implementation, interpretation, or evaluation of cost-benefit analysis within Development Economics, particularly where the Development Policy and Evaluation module establishes its technical context.', 'SSD_COURSE_058_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M6_S3', 'impact evaluation', '3', 'impact evaluation: Evaluation designed to estimate whether and to what extent an intervention caused observed changes in specified outcomes, using an appropriate counterfactual or identification strategy. In Development Policy and Evaluation, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_058_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M6_S4', 'randomized trials', '4', 'randomized trials: Studies that randomly assign eligible units to treatment or control groups to estimate causal effects. In Development Policy and Evaluation, the focus is on the analysis, design, implementation, interpretation, or evaluation of randomized trials within Development Economics, particularly where the Development Policy and Evaluation module establishes its technical context.', 'SSD_COURSE_058_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M7_S1', 'trade', '1', 'trade: Exchange of goods and services across regions or countries and its effects on production, prices, income, and development. In International Development and Global Integration, the focus is on the analysis, design, implementation, interpretation, or evaluation of trade within Development Economics, particularly where the International Development and Global Integration module establishes its technical context.', 'SSD_COURSE_058_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M7_S2', 'aid', '2', 'aid: Transfer of financial, technical, or material resources intended to support development or humanitarian objectives. In International Development and Global Integration, the focus is on the analysis, design, implementation, interpretation, or evaluation of aid within Development Economics, particularly where the International Development and Global Integration module establishes its technical context.', 'SSD_COURSE_058_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M7_S3', 'migration', '3', 'migration: Movement of people between geographic locations, considered in relation to its drivers, patterns, consequences, and institutional or socioeconomic context. In International Development and Global Integration, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_058_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M7_S4', 'technology transfer', '4', 'technology transfer: Movement and adoption of technologies, knowledge, skills, or production practices across firms, sectors, or countries. In International Development and Global Integration, the focus is on the analysis, design, implementation, interpretation, or evaluation of technology transfer within Development Economics, particularly where the International Development and Global Integration module establishes its technical context.', 'SSD_COURSE_058_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M7_S5', 'global value chains', '5', 'global value chains: Production processes distributed across multiple countries or locations with different stages contributing to a final product or service. In International Development and Global Integration, the focus is on the analysis, design, implementation, interpretation, or evaluation of global value chains within Development Economics, particularly where the International Development and Global Integration module establishes its technical context.', 'SSD_COURSE_058_M7_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M1_S1', 'policy problems', '1', 'policy problems: policy problems in Public Policy and Governance concerns legal rules, institutional mechanisms, duties, procedures, and compliance considerations governing policy problems. In Policy Concepts and Institutions, the focus is on the analysis, design, implementation, interpretation, or evaluation of policy problems within Public Policy and Governance, particularly where the Policy Concepts and Institutions module establishes its technical context.', 'SSD_COURSE_059_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M1_S2', 'institutions', '2', 'institutions: Formal rules, organisations, and procedures that structure public authority, decision-making, and implementation. In Policy Concepts and Institutions, the focus is on the analysis, design, implementation, interpretation, or evaluation of institutions within Public Policy and Governance, particularly where the Policy Concepts and Institutions module establishes its technical context.', 'SSD_COURSE_059_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M1_S3', 'actors', '3', 'actors: Individuals, organisations, agencies, firms, civil-society groups, or other stakeholders that influence a policy process. In Policy Concepts and Institutions, the focus is on the analysis, design, implementation, interpretation, or evaluation of actors within Public Policy and Governance, particularly where the Policy Concepts and Institutions module establishes its technical context.', 'SSD_COURSE_059_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M1_S4', 'policy instruments', '4', 'policy instruments: Tools through which public authorities seek to influence behaviour, allocate resources, regulate activity, or achieve defined policy objectives. In Policy Concepts and Institutions, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_059_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M2_S1', 'agenda setting', '1', 'agenda setting refers to the process through which some public problems receive attention and become priorities for government action. In Policy Formulation, the focus is on the analysis, design, implementation, interpretation, or evaluation of agenda setting within Public Policy and Governance, particularly where the Policy Formulation module establishes its technical context.', 'SSD_COURSE_059_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M2_S2', 'problem definition', '2', 'problem definition: Framing a public issue in ways that identify its causes, affected groups, scope, and possible policy responses. In Policy Formulation, the focus is on the analysis, design, implementation, interpretation, or evaluation of problem definition within Public Policy and Governance, particularly where the Policy Formulation module establishes its technical context.', 'SSD_COURSE_059_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M2_S3', 'evidence use', '3', 'evidence use refers to the systematic use of research, administrative data, evaluation findings, and other credible information in policy decisions. In Policy Formulation, the focus is on the analysis, design, implementation, interpretation, or evaluation of evidence use within Public Policy and Governance, particularly where the Policy Formulation module establishes its technical context.', 'SSD_COURSE_059_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M2_S4', 'policy design', '4', 'policy design: Formulating the objectives, instruments, target groups, implementation mechanisms, and expected effects of a public policy. In Policy Formulation, the focus is on the analysis, design, implementation, interpretation, or evaluation of policy design within Public Policy and Governance, particularly where the Policy Formulation module establishes its technical context.', 'SSD_COURSE_059_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M2_S5', 'stakeholder analysis', '5', 'stakeholder analysis: Identifying stakeholders, their interests, influence, affected interests, and relationships to inform policy formulation and implementation. In Policy Formulation, the focus is on the analysis, design, implementation, interpretation, or evaluation of stakeholder analysis within Public Policy and Governance, particularly where the Policy Formulation module establishes its technical context.', 'SSD_COURSE_059_M2_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M3_S1', 'implementation structures', '1', 'implementation structures: Organisational arrangements, responsibilities, processes, and resources through which a policy is put into practice. In Policy Implementation, the focus is on the analysis, design, implementation, interpretation, or evaluation of implementation structures within Public Policy and Governance, particularly where the Policy Implementation module establishes its technical context.', 'SSD_COURSE_059_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M3_S2', 'administrative capacity', '2', 'administrative capacity refers to the ability of public organisations to implement policy effectively using appropriate people, systems, resources, and coordination. In Policy Implementation, the focus is on the analysis, design, implementation, interpretation, or evaluation of administrative capacity within Public Policy and Governance, particularly where the Policy Implementation module establishes its technical context.', 'SSD_COURSE_059_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M3_S3', 'street-level bureaucracy', '3', 'street-level bureaucracy: Front-line public-service work in which officials exercise discretion while implementing policy in direct interaction with citizens. In Policy Implementation, the focus is on the analysis, design, implementation, interpretation, or evaluation of street-level bureaucracy within Public Policy and Governance, particularly where the Policy Implementation module establishes its technical context.', 'SSD_COURSE_059_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M3_S4', 'Policy coordination', '4', 'Policy coordination: Alignment of actions, responsibilities, instruments, and decisions among public institutions or policy actors to reduce conflict, duplication, and implementation gaps. In Policy Implementation, the focus is on curricular scope: Public Policy and Governance; The concept is represented at the level of the stated mechanism, properties, constraints, and application criteria.', 'SSD_COURSE_059_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M4_S1', 'regulatory institutions', '1', 'regulatory institutions: Public bodies responsible for developing, administering, monitoring, or enforcing regulatory requirements. In Governance and Regulation, the focus is on the analysis, design, implementation, interpretation, or evaluation of regulatory institutions within Public Policy and Governance, particularly where the Governance and Regulation module establishes its technical context.', 'SSD_COURSE_059_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M4_S2', 'accountability', '2', 'accountability refers to the obligation of public actors to explain decisions and actions and face appropriate scrutiny or consequences. In Governance and Regulation, the focus is on the analysis, design, implementation, interpretation, or evaluation of accountability within Public Policy and Governance, particularly where the Governance and Regulation module establishes its technical context.', 'SSD_COURSE_059_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M4_S3', 'transparency', '3', 'transparency: Availability and clarity of information needed to understand public decisions, processes, spending, and performance. In Governance and Regulation, the focus is on the analysis, design, implementation, interpretation, or evaluation of transparency within Public Policy and Governance, particularly where the Governance and Regulation module establishes its technical context.', 'SSD_COURSE_059_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M4_S4', 'participation', '4', 'participation: Involvement of affected people or stakeholders in public decision-making and policy processes. In Governance and Regulation, the focus is on the analysis, design, implementation, interpretation, or evaluation of participation within Public Policy and Governance, particularly where the Governance and Regulation module establishes its technical context.', 'SSD_COURSE_059_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M4_S5', 'regulatory design', '5', 'regulatory design: Designing rules, standards, enforcement mechanisms, and institutional arrangements to achieve specified public objectives while considering compliance and implementation costs. In Governance and Regulation, the focus is on the analysis, design, implementation, interpretation, or evaluation of regulatory design within Public Policy and Governance, particularly where the Governance and Regulation module establishes its technical context.', 'SSD_COURSE_059_M4_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M5_S1', 'budgets', '1', 'budgets: Authorised plans showing expected public revenues, expenditures, and resource allocations for a defined period. In Public Finance and Policy, the focus is on the analysis, design, implementation, interpretation, or evaluation of budgets within Public Policy and Governance, particularly where the Public Finance and Policy module establishes its technical context.', 'SSD_COURSE_059_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M5_S2', 'public expenditure', '2', 'public expenditure: Government spending on services, programmes, transfers, infrastructure, administration, and other public purposes. In Public Finance and Policy, the focus is on the analysis, design, implementation, interpretation, or evaluation of public expenditure within Public Policy and Governance, particularly where the Public Finance and Policy module establishes its technical context.', 'SSD_COURSE_059_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M5_S3', 'fiscal instruments', '3', 'fiscal instruments: Taxes, public spending, transfers, subsidies, and related budgetary measures used to influence economic activity and achieve policy objectives. In Public Finance and Policy, the focus is on the analysis, design, implementation, interpretation, or evaluation of fiscal instruments within Public Policy and Governance, particularly where the Public Finance and Policy module establishes its technical context.', 'SSD_COURSE_059_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M5_S4', 'procurement', '4', 'procurement refers to the process through which public bodies acquire goods, works, or services under defined rules and procedures. In Public Finance and Policy, the focus is on the analysis, design, implementation, interpretation, or evaluation of procurement within Public Policy and Governance, particularly where the Public Finance and Policy module establishes its technical context.', 'SSD_COURSE_059_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_059_M5_S5', 'Public resource allocation', '5', 'Public resource allocation: Allocation of scarce public resources across programmes, services, or policy priorities subject to budget constraints, policy objectives, institutional rules, and distributional considerations. In Public Finance and Policy, the focus is on curricular scope: Public Policy and Governance; The concept is represented at the level of the stated mechanism, properties, constraints, and application criteria.', 'SSD_COURSE_059_M5_S5', 'Semantically_Audited', 'Active', '4.0') ON CONFLICT DO NOTHING;